import { announce, definePrimitive } from "@ui-sdk/core"

import { unavailable } from "@/lib/action-refusal"
import { toTime, type Instant } from "@/lib/time"

/** What `onCreate` resolves to. `url` is the secret: the panel shows it once and never stores it in state. */
type InvitationLink = { id: string; url: string; expiresAt: Instant }

/** What `create` resolves to: never the URL. */
type InvitationCreated = { id: string; expiresAt: number }

/** The new link as agents and state see it: its id and expiry, never its URL. */
type InvitationLinkState = { id: string; expiresAt: number; expired: boolean }

type InvitationRole = { value: string; label: string }

type InvitationPanelOptions = {
  onCreate?: (request: { role: string | undefined }) => InvitationLink | PromiseLike<InvitationLink>
  /** Revokes an invitation, pending or the new link, once the confirmation is accepted. */
  onRevoke?: (id: string) => unknown
  roles?: readonly InvitationRole[]
  /** The role the role choice holds; `create(role)` overrides it. */
  role?: string | null
  /** The pending invitations as agents read them, by id. */
  invitations?: readonly InvitationRole[]
  createdAnnouncement?: string
  copiedAnnouncement?: string
  expiredAnnouncement?: string
}

type InvitationPanelState = {
  link: InvitationLinkState | null
  creating: boolean
  copied: boolean
  error: unknown
  revoking: string | null
}

const COPIED_FOR = 2000

const isThenable = (value: unknown): value is PromiseLike<unknown> =>
  typeof value === "object" && value !== null && "then" in value && typeof value.then === "function"

const sameName = (a: string, b: string) => a.localeCompare(b, undefined, { sensitivity: "base" }) === 0

const invitationPanel = definePrimitive({
  name: "invitation-panel",
  options: {
    onCreate: "callback",
    onRevoke: "callback",
    roles: "value",
    role: "value",
    invitations: "value",
    createdAnnouncement: "string",
    copiedAnnouncement: "string",
    expiredAnnouncement: "string",
  },
  controlled: ["link", "creating", "copied"],
  state: (_options: InvitationPanelOptions): InvitationPanelState => ({
    link: null,
    creating: false,
    copied: false,
    error: null,
    revoking: null,
  }),
  api: (context) => {
    let heldUrl: string | undefined
    let copiedTimer: ReturnType<typeof setTimeout> | undefined
    let destroyed = false
    const forgetLink = () => {
      heldUrl = undefined
      clearTimeout(copiedTimer)
    }
    context.onDestroy(() => {
      destroyed = true
      forgetLink()
    })

    const pickRole = (role: unknown, call: { event?: Event | undefined }) => {
      const { roles, role: chosen } = context.options()
      if (!roles || roles.length === 0) return { role: undefined }
      if (role === undefined || role === null) {
        if (chosen) return { role: chosen }
        return { refusal: unavailable("create", "needs a role", call) }
      }
      const match = roles.find(
        (candidate) => candidate.value === role || (typeof role === "string" && sameName(candidate.label, role)),
      )
      if (match) return { role: match.value }
      const names = roles.map((candidate) => candidate.label).join(", ")
      return { refusal: unavailable("create", `takes one of these roles: ${names}`, call) }
    }

    const api = {
      /**
       * Asks `onCreate` for a new one-time link, with `role` (a role's value or label) or the role choice's. Resolves
       * to `{ id, expiresAt }`; the URL only ever reaches the screen, once, and the clipboard through `copy`.
       */
      create(role?: unknown, event?: Event): Promise<InvitationCreated> | false {
        const call = { event }
        if (context.store.get().creating) {
          return unavailable("create", "isn't available while an invitation is being created", call)
        }
        const picked = pickRole(role, call)
        if ("refusal" in picked) return false
        const { onCreate } = context.options()
        if (!onCreate) return unavailable("create", "isn't available: the panel has no onCreate", call)
        forgetLink()
        context.store.set({ creating: true, error: null, copied: false, link: null })
        let request: InvitationLink | PromiseLike<InvitationLink>
        try {
          request = onCreate({ role: picked.role })
        } catch (error) {
          context.store.set({ creating: false, error })
          return Promise.reject(error instanceof Error ? error : new Error(String(error)))
        }
        return Promise.resolve(request).then(
          (link) => {
            const expiresAt = toTime(link.expiresAt)
            if (destroyed) return { id: link.id, expiresAt }
            heldUrl = link.url
            context.store.set({
              creating: false,
              link: { id: link.id, expiresAt, expired: expiresAt <= Date.now() },
            })
            const { createdAnnouncement } = context.options()
            if (createdAnnouncement) announce(createdAnnouncement)
            return { id: link.id, expiresAt }
          },
          (error: unknown) => {
            if (!destroyed) context.store.set({ creating: false, error })
            throw error
          },
        )
      },
      /** Writes the new link to the clipboard. Resolves to `"copied"`, never to the link. */
      copy(event?: Event): Promise<"copied" | false> | false {
        const call = { event }
        const { link } = context.store.get()
        if (!link || heldUrl === undefined) {
          return unavailable(
            "copy",
            "isn't available: no new link is held, and a link shows only once. Create a new one",
            call,
          )
        }
        if (link.expired || link.expiresAt <= Date.now()) {
          api.expire()
          return unavailable("copy", "isn't available: the link has expired. Create a new one", call)
        }
        const clipboard = typeof navigator === "undefined" ? undefined : navigator.clipboard
        if (!clipboard) return unavailable("copy", "isn't available: the page has no clipboard access", call)
        return clipboard.writeText(heldUrl).then(
          () => {
            clearTimeout(copiedTimer)
            context.store.set({ copied: true })
            copiedTimer = setTimeout(() => context.store.set({ copied: false }), COPIED_FOR)
            const { copiedAnnouncement } = context.options()
            if (copiedAnnouncement) announce(copiedAnnouncement)
            return "copied" as const
          },
          () => unavailable("copy", "was blocked by the browser", call),
        )
      },
      /**
       * Asks to revoke an invitation by id, pending or the new link: it opens the confirmation, whose confirm button
       * needs a person's approval for an agent.
       */
      revoke(id: unknown, event?: Event) {
        const call = { event }
        const { link } = context.store.get()
        const known =
          typeof id === "string" &&
          (link?.id === id || (context.options().invitations ?? []).some((invitation) => invitation.value === id))
        if (!known) return unavailable("revoke", `has no invitation with the id ${JSON.stringify(id)}`, call)
        context.store.set({ revoking: id })
        return true
      },
      /** Runs `onRevoke` for the invitation being confirmed; a revoked new link is forgotten. */
      confirmRevoke() {
        const id = context.store.get().revoking
        if (id === null) return undefined
        const forgetIfNew = () => {
          if (context.store.get().link?.id !== id) return
          forgetLink()
          context.store.set({ link: null, copied: false })
        }
        const result = context.options().onRevoke?.(id)
        if (isThenable(result)) return Promise.resolve(result).then(forgetIfNew)
        forgetIfNew()
        return undefined
      },
      closeRevoke() {
        if (context.store.get().revoking !== null) context.store.set({ revoking: null })
      },
      /** Drops the new link and its URL. */
      dismiss() {
        forgetLink()
        if (context.store.get().link !== null) context.store.set({ link: null, copied: false })
        return true
      },
      /** Marks the new link expired and drops its URL. */
      expire() {
        const { link } = context.store.get()
        forgetLink()
        if (!link || link.expired) return
        context.store.set({ link: { ...link, expired: true }, copied: false })
        const { expiredAnnouncement } = context.options()
        if (expiredAnnouncement) announce(expiredAnnouncement)
      },
      agentItems() {
        return context.options().invitations ?? []
      },
      /** The new link's URL, for the one place that shows it; never put it in state, attributes or announcements. */
      linkUrl() {
        return heldUrl
      },
    }
    return api
  },
  slots: (slot) => ({
    root: slot<{}, InvitationPanelState>({
      state: (state) => ({ ...state }),
      attrs: (state) => ({
        role: "group",
        "aria-busy": state.creating ? "true" : undefined,
        "data-creating": state.creating ? "" : undefined,
        "data-has-link": state.link && !state.link.expired ? "" : undefined,
      }),
    }),
  }),
  agent: {
    actions: ["create", "copy", "revoke", "dismiss"],
    items: (api) => api.agentItems(),
  },
})

export { invitationPanel }
export type {
  InvitationCreated,
  InvitationLink,
  InvitationLinkState,
  InvitationPanelOptions,
  InvitationPanelState,
  InvitationRole,
}

"use client"

import { useCallback, useEffect, useEffectEvent, useSyncExternalStore } from "react"

type ExpiryPhase = "later" | "soon" | "expired"

const SOON_MS = 120_000
const LONGEST_TIMEOUT_MS = 2 ** 31 - 1

function phaseAt(expiresAt: number, now: number): ExpiryPhase {
  const left = expiresAt - now
  if (left <= 0) return "expired"
  return left <= SOON_MS ? "soon" : "later"
}

/**
 * Runs `onExpire` once `expiresAt` (epoch ms) passes, with one timeout per boundary and none while the page is hidden;
 * coming back checks the clock again. `soon` is true in the last two minutes, for a countdown by the second.
 */
function useInvitationExpiry(expiresAt: number, onExpire: () => void) {
  const subscribe = useCallback(
    (notify: () => void) => {
      let timer: ReturnType<typeof setTimeout> | undefined
      const arm = () => {
        clearTimeout(timer)
        timer = undefined
        notify()
        if (document.hidden) return
        const left = expiresAt - Date.now()
        if (left <= 0) return
        const nextBoundary = left > SOON_MS ? left - SOON_MS : left
        timer = setTimeout(arm, Math.min(nextBoundary, LONGEST_TIMEOUT_MS))
      }
      arm()
      document.addEventListener("visibilitychange", arm)
      return () => {
        clearTimeout(timer)
        document.removeEventListener("visibilitychange", arm)
      }
    },
    [expiresAt],
  )
  const phase = useSyncExternalStore(
    subscribe,
    () => phaseAt(expiresAt, Date.now()),
    (): ExpiryPhase => "later",
  )
  const expire = useEffectEvent(onExpire)

  useEffect(() => {
    if (phase === "expired") expire()
  }, [phase])

  return { soon: phase === "soon", expired: phase === "expired" }
}

export { useInvitationExpiry }

"use client"

import { usePart, usePrimitive } from "@ui-sdk/react/primitive"
import { CheckIcon, CopyIcon } from "lucide-react"
import { useId, useState, type ReactNode } from "react"

import { Alert, AlertDescription } from "@/components/ui/alert"
import { Button } from "@/components/ui/button"
import { ConfirmDialog } from "@/components/ui/confirm-dialog"
import { DataState, type DataStatus } from "@/components/ui/data-state"
import { Field, FieldLabel } from "@/components/ui/field"
import {
  invitationPanel,
  type InvitationCreated,
  type InvitationLink,
  type InvitationLinkState,
  type InvitationPanelState,
  type InvitationRole,
} from "@/components/ui/invitation-panel-primitive"
import { List, ListItem } from "@/components/ui/list-item"
import { RelativeTime } from "@/components/ui/relative-time"
import { Select } from "@/components/ui/select"
import { useInvitationExpiry } from "@/components/ui/use-invitation-expiry"
import type { Instant } from "@/lib/time"
import { cn } from "@/lib/utils"

/** A pending invitation. It never carries the link: a lost link is revoked and a new one created. */
type Invitation = {
  id: string
  /** The value of one of `roles`. */
  role?: string
  createdBy: string
  expiresAt: Instant
}

/** The panel's visible text. None has a default: pass it in the page's language. */
type InvitationPanelText = {
  create: ReactNode
  /** The role choice's label, when `roles` is given. */
  role?: ReactNode
  createError: ReactNode
  newLink: ReactNode
  /** Under `newLink`, like "Copy it now: it won't be shown again." */
  newLinkDescription?: ReactNode
  copy: ReactNode
  copied: ReactNode
  /** The new link's and each row's expiry, around a live relative time: (time) => <>Expires {time}</>. */
  expiresIn: (time: ReactNode) => ReactNode
  /** Shown, and read, when the new link expires. */
  expired: string
  revoke: ReactNode
  revokeTitle: ReactNode
  revokeDescription?: ReactNode
  /** The confirmation's button; keep it apart from `revoke`, so an agent's press finds this one. */
  revokeConfirm: ReactNode
  /** What a person approves when an agent revokes, like "Revokes the invitation; its link stops working". */
  revokeAgentConfirm: string
  dismiss: ReactNode
  /** The pending list's heading and name. */
  pending: string
  createdBy: (name: string) => string
  emptyTitle: ReactNode
  errorTitle: ReactNode
  retry?: ReactNode
}

/** Names and announcements for screen readers and agents; English by default. */
type InvitationPanelLabels = {
  created: string
  copiedAnnouncement: string
  /** Names the new link's revoke button. */
  revokeNewLink: string
  /** Names a row's revoke button. */
  revokeInvitation: (invitation: { role: string | undefined; createdBy: string }) => string
  cancel?: ReactNode
}

const invitationPanelLabels: InvitationPanelLabels = {
  created: "Invitation link created",
  copiedAnnouncement: "Link copied",
  revokeNewLink: "Revoke new link",
  revokeInvitation: ({ role, createdBy }) =>
    role === undefined ? `Revoke invitation from ${createdBy}` : `Revoke ${role} invitation from ${createdBy}`,
}

type InvitationPanelProps = {
  /** Names the panel for screen readers and agents, like "Invitations". */
  "aria-label": string
  /** Creates an invitation and resolves to its one-time `url`, its `id` and when it expires. */
  onCreate: (request: { role: string | undefined }) => InvitationLink | PromiseLike<InvitationLink>
  /** Revokes an invitation by id, after the confirmation; a returned Promise keeps it pending. */
  onRevoke: (id: string) => unknown
  /** The roles an invitation can grant; with them, the panel shows a role choice. */
  roles?: readonly InvitationRole[]
  defaultRole?: string
  invitations?: readonly Invitation[]
  /** The pending list's load state, for DataState. `success` by default. */
  status?: DataStatus
  error?: unknown
  onRetry?: () => unknown
  text: InvitationPanelText
  labels?: Partial<InvitationPanelLabels>
  /** The locale of the relative expiry times; the page's by default. */
  locale?: string
  className?: string
}

const ignoreRefusal = () => undefined

const noInvitations: readonly Invitation[] = []

const rootAttributes: Record<`data-${string}`, string> = { "data-slot": "invitation-panel" }

function NewLink({
  link,
  url,
  copied,
  text,
  labels,
  onCopy,
  onRevoke,
  onDismiss,
  onExpire,
  locale,
}: {
  locale: string | undefined
  link: InvitationLinkState
  url: string | undefined
  copied: boolean
  text: InvitationPanelText
  labels: InvitationPanelLabels
  onCopy: (event: Event) => void
  onRevoke: (event: Event) => void
  onDismiss: () => void
  onExpire: () => void
}) {
  const headingId = useId()
  const { soon } = useInvitationExpiry(link.expiresAt, onExpire)
  const shown = !link.expired && url !== undefined
  return (
    <section
      data-slot="invitation-panel-link"
      data-expired={link.expired ? "" : undefined}
      aria-labelledby={headingId}
      className="flex flex-col gap-items rounded-surface border border-success-border bg-success-soft/(--glass-opacity) px-inset-item py-inset-item data-expired:border-border data-expired:bg-muted"
    >
      <div className="flex flex-col gap-inline">
        <h3 id={headingId} className="text-title-sm">
          {text.newLink}
        </h3>
        {text.newLinkDescription === undefined ? null : (
          <p className="text-body-sm text-muted-foreground">{text.newLinkDescription}</p>
        )}
      </div>
      {shown ? (
        <div
          data-slot="invitation-panel-url"
          data-agent-hidden=""
          translate="no"
          className="rounded-control border bg-background px-control-x py-inset-item font-mono text-body-sm break-all select-all"
        >
          {url}
        </div>
      ) : (
        <p data-slot="invitation-panel-expired" className="text-body-sm font-medium">
          {text.expired}
        </p>
      )}
      <div className="flex flex-wrap items-center gap-items">
        {shown ? (
          <Button size="sm" onClick={(event) => onCopy(event.nativeEvent)}>
            {copied ? <CheckIcon /> : <CopyIcon />}
            {copied ? text.copied : text.copy}
          </Button>
        ) : null}
        {link.expired ? null : (
          <span className="text-caption text-muted-foreground">
            {text.expiresIn(<RelativeTime value={link.expiresAt} locale={locale} intervalMs={soon ? 1000 : 30_000} />)}
          </span>
        )}
        <span className="ms-auto flex flex-wrap items-center gap-items">
          {link.expired ? null : (
            <Button
              size="sm"
              variant="outline"
              aria-label={labels.revokeNewLink}
              onClick={(event) => onRevoke(event.nativeEvent)}
            >
              {text.revoke}
            </Button>
          )}
          <Button size="sm" variant="ghost" onClick={onDismiss}>
            {text.dismiss}
          </Button>
        </span>
      </div>
    </section>
  )
}

function InvitationPanel({
  "aria-label": label,
  onCreate,
  onRevoke,
  roles,
  defaultRole,
  invitations = noInvitations,
  status = "success",
  error,
  onRetry,
  text,
  labels: overrides,
  locale,
  className,
}: InvitationPanelProps) {
  const labels = { ...invitationPanelLabels, ...overrides }
  const [role, setRole] = useState<string | null>(defaultRole ?? roles?.[0]?.value ?? null)
  const roleLabel = (value: string | undefined) => roles?.find((candidate) => candidate.value === value)?.label ?? value
  const agentInvitations = invitations.map((invitation) => ({
    value: invitation.id,
    label: [roleLabel(invitation.role), text.createdBy(invitation.createdBy)].filter(Boolean).join(", "),
  }))
  const handle = usePrimitive(invitationPanel, {
    onCreate,
    onRevoke,
    roles,
    role,
    invitations: agentInvitations,
    createdAnnouncement: labels.created,
    copiedAnnouncement: labels.copiedAnnouncement,
    expiredAnnouncement: text.expired,
  })
  const { api } = handle
  const pendingHeadingId = useId()

  return usePart(
    handle,
    "root",
    {},
    {
      ...rootAttributes,
      "aria-label": label,
      className: cn("flex min-w-0 flex-col gap-group", className),
      children: (state: InvitationPanelState) => (
        <>
          <div data-slot="invitation-panel-create" className="flex flex-wrap items-end gap-items">
            {roles && roles.length > 0 ? (
              <Field className="min-w-40 flex-1">
                <FieldLabel>{text.role}</FieldLabel>
                <Select options={roles} value={role} onValueChange={setRole} />
              </Field>
            ) : null}
            <Button
              loading={state.creating}
              onClick={(event) => {
                const created = api.create(undefined, event.nativeEvent)
                if (created) created.then(undefined, ignoreRefusal)
              }}
            >
              {text.create}
            </Button>
          </div>
          {state.error === null ? null : (
            <Alert data-slot="invitation-panel-error" tone="destructive" live>
              <AlertDescription className="text-foreground">{text.createError}</AlertDescription>
            </Alert>
          )}
          {state.link === null ? null : (
            <NewLink
              key={state.link.id}
              link={state.link}
              url={api.linkUrl()}
              copied={state.copied}
              text={text}
              labels={labels}
              onCopy={(event) => {
                const copied = api.copy(event)
                if (copied) copied.then(undefined, ignoreRefusal)
              }}
              onRevoke={(event) => {
                if (state.link) api.revoke(state.link.id, event)
              }}
              onDismiss={() => api.dismiss()}
              onExpire={() => api.expire()}
              locale={locale}
            />
          )}
          <section
            data-slot="invitation-panel-pending"
            aria-labelledby={pendingHeadingId}
            className="flex flex-col gap-items"
          >
            <h3 id={pendingHeadingId} className="text-title-sm">
              {text.pending}
            </h3>
            <DataState
              status={status}
              data={invitations}
              error={error}
              size="inline"
              {...(onRetry && text.retry !== undefined
                ? { onRetry, labels: { errorTitle: text.errorTitle, retry: text.retry, emptyTitle: text.emptyTitle } }
                : { labels: { errorTitle: text.errorTitle, emptyTitle: text.emptyTitle } })}
            >
              {(rows) => (
                <List aria-label={text.pending}>
                  {rows.map((invitation) => {
                    const roleName = roleLabel(invitation.role)
                    const creator = text.createdBy(invitation.createdBy)
                    return (
                      <ListItem
                        key={invitation.id}
                        id={invitation.id}
                        title={roleName ?? creator}
                        subtitle={
                          <>
                            {roleName === undefined ? null : <>{creator} · </>}
                            {text.expiresIn(<RelativeTime value={invitation.expiresAt} locale={locale} />)}
                          </>
                        }
                        actions={
                          <Button
                            size="sm"
                            variant="outline"
                            aria-label={labels.revokeInvitation({ role: roleName, createdBy: invitation.createdBy })}
                            onClick={(event) => api.revoke(invitation.id, event.nativeEvent)}
                          >
                            {text.revoke}
                          </Button>
                        }
                      />
                    )
                  })}
                </List>
              )}
            </DataState>
          </section>
          <ConfirmDialog
            open={state.revoking !== null}
            onOpenChange={(open) => {
              if (!open) api.closeRevoke()
            }}
            tone="destructive"
            title={text.revokeTitle}
            description={text.revokeDescription}
            confirmLabel={text.revokeConfirm}
            agentConfirm={text.revokeAgentConfirm}
            labels={labels.cancel === undefined ? undefined : { cancel: labels.cancel }}
            onConfirm={() => api.confirmRevoke()}
          />
        </>
      ),
    },
  )
}

export { InvitationPanel, invitationPanelLabels }
export type {
  Invitation,
  InvitationCreated,
  InvitationLink,
  InvitationPanelLabels,
  InvitationPanelProps,
  InvitationPanelText,
  InvitationRole,
}
